#!/usr/bin/env bash\nset -euo pipefail\n\n# Mock rationale: In a real action we would call the GitHub API; here we just echo labels.\n\nTITLE="${PR_TITLE:-}"\nTOKEN="${GITHUB_TOKEN:-}"\n\n# Determine labels based on keywords\nlabels=()\nlower_title=$(echo "$TITLE" | tr '[:upper:]' '[:lower:]')\nif [[ "$lower_title" == *"bug"* ]]; then\n  labels+=("bug")\nfi\nif [[ "$lower_title" == *"feature"* ]]; then\n  labels+=("enhancement")\nfi\nif [[ "$lower_title" == *"doc"* ]]; then\n  labels+=("documentation")\nfi\n\n# Add a random emoji label\nemojis=("🚀" "🐛" "✨" "📚" "⚡")\n# Mock rationale: Use deterministic selection for tests; pick first.\nemoji="${emojis[0]}"\nlabels+=("$emoji")\n\n# Output labels\njoined=$(IFS=,; echo "${labels[*]}")\necho "Labels to add: $joined"\n\n# In a real action we would POST to the GitHub API.\n# For this mock utility we just set an output.\nif [[ -n "${GITHUB_OUTPUT:-}" ]]; then\n  echo "labels=$joined" >> "$GITHUB_OUTPUT"\nfi
